const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, schools;
const sourceLink = () => `<a href="${esc(data.meta.sourceUrl)}" target="_blank" rel="noreferrer">Official BPS spreadsheet ↗</a>`;
function renderMethodology(){
 const memo='https://resources.finalsite.net/images/v1728696391/bostonpublicschoolsorg/xs6soln38fh8vphhgglu/finallongtermfacilitiesplanrubricandbuildingmodelsmemo.pdf';
 const survey='https://www.bostonpublicschools.org/students-families/surveys/past-survey-results/2025-2026';
 $('method-content').innerHTML=`<div class="method-grid"><div><h3>Why this explorer exists</h3><p>School leaders must decide where to investigate facilities needs. This independent project organizes public evidence for BPS capital planning and facilities staff, with school principals and community representatives as secondary users. It supports site visits and needs assessments, not school closures, mergers, or final funding allocations.</p><h3>How the data were collected</h3><p>BPS describes evaluating school spaces for educational adequacy. Its <a href="${memo}" target="_blank" rel="noreferrer">planning memo</a> explains that building walkthroughs, floor plans, and facilities assessments informed Building Experience Scores. Administrative measures are compiled in the planning spreadsheet; detailed field-level collection protocols are not supplied in the CSV.</p><p>This project downloaded the official sheet as CSV on September 21, 2026, preserved it unchanged, converted numeric fields, and retained source row numbers. It conducted no student survey. ${sourceLink()}</p></div><div><h3>What the dates mean</h3><p><strong>Source update:</strong> November 8, 2025, as labeled in the sheet.<br><strong>Access date:</strong> September 21, 2026.<br><strong>Measurement periods:</strong> mixed. Utilization and the retained absenteeism measure are five-year averages, with exact component years unspecified. Enrollment, capacity, and score reference dates are not specified in this export.</p><h3>Transparent review signals</h3><p>“Lower score” means 0–1 out of 4; “above capacity” in this analysis means reported five-year average utilization greater than 100%. These are project-defined screening rules, not BPS priority categories. No composite ranking or investment-return estimate is calculated.</p><p>All findings use records in the current filters. Score percentages divide by records with valid scores. Utilization percentages divide by valid utilization records. Combined signals use records with both values. Counts are not weighted by enrollment.</p></div></div>
 <div id="limitations" class="limitations"><h3>Read the evidence with its limits</h3><ul><li><strong>Missing and qualified values:</strong> ${data.audit.missingScore} of ${schools.length} records lack a score; ${data.audit.missingUtilization} lack utilization. One capacity is “371*”; the footnote is not explained in the CSV, so the raw value is shown but excluded from numeric comparisons. Blanks and unavailable markers become null, never zero.</li><li><strong>School ≠ building:</strong> the ${schools.length} distinct source codes include campus-specific records. Related sites are preserved, not consolidated. No identical normalized street addresses were found, but that does not rule out shared facilities. The source explicitly flags Horace Mann as shared with Warren-Prescott. Capacity is never summed.</li><li><strong>Historical operating status:</strong> this is not a verified directory of currently open schools. Moves, renamed schools, closures, and mergers can affect interpretation. Check <a href="${data.meta.landingUrl}" target="_blank" rel="noreferrer">current BPS capital planning information</a> and confirm each site before acting.</li><li><strong>Survey coverage:</strong> school-level 2026 student survey results have not been reliably extracted and matched to these campus records, so no student belonging or safety measures are shown. Absenteeism is retained in the data download, not used as a substitute for student experience.</li><li><strong>Participation and privacy:</strong> BPS reports withholding school survey results below 30% participation and groups smaller than 10. Respondents may differ from nonrespondents, and suppressed results must not be read as negative feedback. See the <a href="${survey}" target="_blank" rel="noreferrer">2026 survey publication</a>.</li><li><strong>Uncertainty:</strong> rounded source values, undocumented reference years, aggregate reporting, and imperfect campus matching limit comparisons. The data do not support confidence intervals for investment effects. A facilities score does not describe overall school quality or every student’s experience.</li><li><strong>No causal claim:</strong> coinciding signals cannot establish that facilities cause student outcomes. Current site assessments, student consultation, intervention evidence, and cost estimates are needed before funding decisions.</li></ul></div>
 <details open><summary>Data dictionary · definitions, units & periods</summary><div class="dictionary"><table><caption class="sr-only">Data dictionary for fields used by this explorer</caption><thead><tr><th>Field</th><th>Definition / unit</th><th>Period</th><th>Treatment / source</th></tr></thead><tbody>${[
 ['School code / name','BPS source identifier and name; school or campus record.','Historical source snapshot','Codes remain strings, including letter suffixes; no consolidation.'],
 ['Neighborhood / address','Reported neighborhood and street address; text.','Not specified','Source labels retained; not used to infer current operating status.'],
 ['Grade level / grades served','BPS grouping and grade range; categorical.','Not specified','Filters use the original groupings, not inferred grades.'],
 ['Building Experience Score','Ordinal score, 0–4. Higher indicates physical spaces support more components of the BPS high-quality student experience. Not a satisfaction or structural safety score.','Assessment date not specified in CSV','Missing values excluded from score denominators. No mean score or weighted rank.'],
 ['Utilization','Reported utilization, percent of capacity. The source does not document the detailed averaging formula.','5-year average; component years unspecified','Preserved as reported. Never recalculated from enrollment / capacity.'],
 ['Enrollment','Reported number of enrolled students.','Reference date unspecified','Missing remains null. Not used to weight findings.'],
 ['Capacity','Reported capacity in places. Detailed operational definition is not supplied in CSV.','Reference date unspecified','No totals across campuses. Qualified “371*” is retained as raw text and excluded from numeric comparisons.'],
 ['Chronic absenteeism ≥10%','Source-reported percent for the “Chronically Absent 10% or More” field; underlying calculation details not provided in CSV. Download only.','5-year average; component years unspecified','Not a student-experience measure; not used in recommendations.'],
 ['Derived findings','Record counts and percentages: qualifying valid records ÷ relevant valid records × 100.','Uses mixed periods above','Unweighted; missing excluded from denominators and separately reported.']
 ].map(([field,definition,period,treatment])=>`<tr><th scope="row">${field}</th><td>${definition}</td><td>${period}</td><td>${treatment} ${sourceLink()}</td></tr>`).join('')}</tbody></table></div></details>
 <details><summary>Sources, reproducibility & data downloads</summary><ol class="sources-list"><li>${sourceLink()} — Boston Public Schools; update label: 11/8/2025. Primary dataset.</li><li><a href="${data.meta.landingUrl}" target="_blank" rel="noreferrer">BPS Long-Term Facilities Planning Data Dashboard</a> — official publishing page and facilities context.</li><li><a href="${memo}" target="_blank" rel="noreferrer">BPS facilities rubric and building models memo</a> — origin and interpretation of the score; publication date not verified here.</li><li><a href="${survey}" target="_blank" rel="noreferrer">BPS 2026 School Climate Survey Results</a> — optional source reviewed, with published confidentiality rules. No survey data merged.</li></ol><p class="chart-foot">All sources accessed September 21, 2026. The original CSV, a cleaned CSV, structured JSON, processing script, and README accompany this project. Missing values are blank in the cleaned CSV and null in JSON; detailed status flags are retained in JSON.</p><div class="download-links"><a href="data/bps-facilities-original.csv" download>Original BPS CSV ↓</a><a href="data/schools-cleaned.csv" download>Cleaned data ↓</a><a href="data/schools.json" download>Data + audit (JSON) ↓</a><a href="data/sources.json" download>Source metadata ↓</a></div></details>`;
}

async function init() {
 try {
  const response = await fetch('data/schools.json');
  if (!response.ok) throw new Error('The data could not be loaded.');
  data = await response.json(); schools = data.schools; renderMethodology();
  if (location.hash) document.getElementById(location.hash.slice(1))?.scrollIntoView();
 } catch (e) {
  $('method-content').textContent = '';
  $('error').hidden = false;
  $('error').textContent = 'Documentation could not be loaded. Please reload the page. ' + e.message;
 }
}
init();
